import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, copyToClipboard, hasWritePrivilege, parseDateMMDDYYYY, time2prettify, AccountYears } from "../../../stores/Utils";

import "./dashboard.css"
import { OpenModal } from "../../../components/DialogHRM";
import { delete_inv_location, getInventoryById, getall_product, sortProducts,  } from "../services/server_fetching";
import { SvgIcon_Cmpt,  } from "../../../components";
import DeleteAlert from "./deleteAlert";
import NoPrivilege from "./NoPrivilege";
import { LocationsLabelsPdf } from "../services/export_service";


const Svg = SvgIcon_Cmpt();

// const UpdProduct = UpdProduct_Cmpt();



const InventoryLocationItem  = ({ data, handleRefreshAll }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			// let frm2 = {"firstName":"Belisario","lastName":"Gonzalez Arevalo","genre":"Male","dateOfBirth":"06/02/1976","placeOfBirth":{"city":"Holguin","state":"Holguin"},"currentAddress":{"No":"4307","street":"Estate Dr","city":"Louisville","state":"Kentucky","zipcode":"40216"},"dob":202536000000}
			//updStore(frmNm, frm2);
			set_obs(gen16CodeId())


			// getInventoryById(data?.inventoryId);
		}
	});

	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}



	const refreshAccs =  () => {
		getall_product(updObs)
	}


	const update = async () => {
		if(hasWritePrivilege()){
			updStore("upd_product", data);
			updStore("upd_product_bck", JSON.parse(JSON.stringify(data)));
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true };
			//modaldata["content"] = <UpdProduct confirm={refreshAccs} />;
			//OpenModal(modaldata);
		}
	}

	
	


	const openSubMayor =  (sba) => {
		

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "80vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true };
		//	modaldata["content"] =  	<ViewSubMayor confirm={refreshAccs} item={data}/>
		// OpenModal(modaldata);
	}


	const deleteComprobante =  () => {
		delete_inv_location(data?.inventoryLocationId, handleRefreshAll);

	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(hasWritePrivilege()){
			if( Date.now() > lastTimeCallModal){
				updStore("lastTimeCallModal", Date.now()+320);
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				modaldata["content"] = <DeleteAlert  label={"Eliminar Registro"} confirm={deleteComprobante} item={data} />
				OpenModal(modaldata);
			}
		}else{
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <NoPrivilege />
			OpenModal(modaldata);
		}
	}

	

	let locationD = `${getStore("locations_ids")?.[data?.locationId]?.areaId  }-${getStore("locations_ids")?.[data?.locationId]?.location  }`
	
	const copyToClpb  =  ()  => {
		copyToClipboard( data?.areaId + "-" + data?.location);
	};


	const print  =  ()  => {
		LocationsLabelsPdf( [data]);
	};

	
	return (
		<div className="item_acc">
			<div className="_dsplFlx item_box product_header">
			<div className="_dsplFlx tr_bar_90 ">
			
				
					<div className="name tr_bar tr_bar_20 centerBx" >
						{`${parseDateMMDDYYYY(data?.date)} ${time2prettify(data?.date,1)}`}
					</div>
					<div className="name tr_bar tr_bar_20 centerBx" style={{marginLeft:14}}>
						{locationD}
					</div>
					<div className="code tr_bar tr_bar_20 centerBx"  style={{marginLeft: 19}} onClick={update}>
						{data?.alphaCode}
					</div>
					<div className="name tr_bar tr_bar_20 centerBx"  style={{marginLeft: 19}} onClick={update}>
						{getStore("ProductsOnScanItems")?.[data?.productId]?.name}
					</div>
					
				</div>
				<div className="flexSpace"/>
				
				{hasWritePrivilege()?
				AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="icon" style={{marginLeft: 19}} onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"} color={"#c62828"}/>
				</div>
				:null}
			</div>
			
		</div>
	)
}
export default InventoryLocationItem;